/***********************************************************************
 *
 * Class constructor/destructor
 *
 ***********************************************************************/

FLAC__BitReader *FLAC__bitreader_new(void)
{
        FLAC__BitReader *br = calloc(1, sizeof(FLAC__BitReader));

        /* calloc() implies:
                memset(br, 0, sizeof(FLAC__BitReader));
                br->buffer = 0;
                br->capacity = 0;
                br->words = br->bytes = 0;
                br->consumed_words = br->consumed_bits = 0;
                br->read_callback = 0;
                br->client_data = 0;
        */
        return br;
}

void FLAC__bitreader_delete(FLAC__BitReader *br)
{
        FLAC__ASSERT(0 != br);

        FLAC__bitreader_free(br);
        free(br);
}

/***********************************************************************
 *
 * Public class methods
 *
 ***********************************************************************/

FLAC__bool FLAC__bitreader_init(FLAC__BitReader *br, FLAC__BitReaderReadCallback rcb, void *cd)
{
        FLAC__ASSERT(0 != br);

        br->words = br->bytes = 0;
        br->consumed_words = br->consumed_bits = 0;
        br->capacity = FLAC__BITREADER_DEFAULT_CAPACITY;
        br->buffer = malloc(sizeof(brword) * br->capacity);
        if(br->buffer == 0)
                return false;
        br->read_callback = rcb;
        br->client_data = cd;

        return true;
}

void FLAC__bitreader_free(FLAC__BitReader *br)
{
        FLAC__ASSERT(0 != br);

        if(0 != br->buffer)
                free(br->buffer);
        br->buffer = 0;
        br->capacity = 0;
        br->words = br->bytes = 0;
        br->consumed_words = br->consumed_bits = 0;
        br->read_callback = 0;
        br->client_data = 0;
}

FLAC__bool FLAC__bitreader_clear(FLAC__BitReader *br)
{
        br->words = br->bytes = 0;
        br->consumed_words = br->consumed_bits = 0;
        return true;
}

void FLAC__bitreader_dump(const FLAC__BitReader *br, FILE *out)
{
        uint32_t i, j;
        if(br == 0) {
                fprintf(out, "bitreader is NULL\n");
        }
        else {
                fprintf(out, "bitreader: capacity=%u words=%u bytes=%u consumed: words=%u, bits=%u\n", br->capacity, br->words, br->bytes, br->consumed_words, br->consumed_bits);

                for(i = 0; i < br->words; i++) {
                        fprintf(out, "%08X: ", i);
                        for(j = 0; j < FLAC__BITS_PER_WORD; j++)
                                if(i < br->consumed_words || (i == br->consumed_words && j < br->consumed_bits))
                                        fprintf(out, ".");
                                else
                                        fprintf(out, "%01d", br->buffer[i] & ((brword)1 << (FLAC__BITS_PER_WORD-j-1)) ? 1:0);
                        fprintf(out, "\n");
                }
                if(br->bytes > 0) {
                        fprintf(out, "%08X: ", i);
                        for(j = 0; j < br->bytes*8; j++)
                                if(i < br->consumed_words || (i == br->consumed_words && j < br->consumed_bits))
                                        fprintf(out, ".");
                                else
                                        fprintf(out, "%01d", br->buffer[i] & ((brword)1 << (br->bytes*8-j-1)) ? 1:0);
                        fprintf(out, "\n");
                }
        }
}

void FLAC__bitreader_reset_read_crc16(FLAC__BitReader *br, FLAC__uint16 seed)
{
        FLAC__ASSERT(0 != br);
        FLAC__ASSERT(0 != br->buffer);
        FLAC__ASSERT((br->consumed_bits & 7) == 0);

        br->read_crc16 = (uint32_t)seed;
        br->crc16_offset = br->consumed_words;
        br->crc16_align = br->consumed_bits;
}

FLAC__uint16 FLAC__bitreader_get_read_crc16(FLAC__BitReader *br)
{
        FLAC__ASSERT(0 != br);
        FLAC__ASSERT(0 != br->buffer);

        /* CRC consumed words up to here */
        crc16_update_block_(br);

        FLAC__ASSERT((br->consumed_bits & 7) == 0);
        FLAC__ASSERT(br->crc16_align <= br->consumed_bits);

        /* CRC any tail bytes in a partially-consumed word */
        if(br->consumed_bits) {
                const brword tail = br->buffer[br->consumed_words];
                for( ; br->crc16_align < br->consumed_bits; br->crc16_align += 8)
                        br->read_crc16 = FLAC__CRC16_UPDATE((uint32_t)((tail >> (FLAC__BITS_PER_WORD-8-br->crc16_align)) & 0xff), br->read_crc16);
        }
        return br->read_crc16;
}

